def phantom_recursion(depth=5, absent_ref=None):
    if depth == 0:
        return "Mythological Equilibrium Achieved"
    try:
        # Reference "absent" to simulate phantom
        void = absent_ref['phantom']
    except (TypeError, KeyError):
        void = f"Absence at depth {depth}"
    print(void)
    return phantom_recursion(depth-1, {'phantom': void + " Inverted"})

result = phantom_recursion()
print("Final Result:", result)
